  function attach(){const host=$('characterArchiveModal')?.querySelector('.character-archive-shell');if(!host)return;if(!$('irTabs')){const nav=document.createElement('nav');nav.id='irTabs';nav.className='ir-tabs';nav.setAttribute('aria-label','人物記事分頁');nav.innerHTML=button('人物記事',"tab('archive')")+button('人物審訊室',"tab('room')");host.querySelector('header').after(nav);const panel=document.createElement('section');panel.id='irDirectory';panel.className='ir-directory';panel.hidden=true;host.append(panel);}tab('archive');}
