  function directory(){const el=$('irDirectory');if(!el)return;const scroll=el,top=scroll.scrollTop;theme(el);const data=room();el.innerHTML=`<div class="ir-directory-head"><small>PRIVATE DOSSIER / INTERROGATION ARCHIVE</small><div class="ir-heading"><h3>人物審訊室</h3>${button('＋ 新增篇章','editVolume()')}</div><p>燈光亮起之後，讓那些未曾說出口的故事，有了回音。</p><span class="ir-case-tag">SUBJECT / ${esc(char()?.name)} · ${data.volumes.length} VOLUMES</span></div><div class="ir-volumes">${data.volumes.length?data.volumes.map((v,vi)=>`<section class="ir-volume" style="--ir-order:${vi}"><div class="ir-volume-number">${String(vi+1).padStart(2,'0')}<small>CASE FILE</small></div><div class="ir-volume-main"><small>CONFIDENTIAL · 人物專屬檔案</small><div class="ir-heading"><h4>${esc(v.title)}</h4><div>${button('編輯',`editVolume('${esc(v.id)}')`)}${button('刪除',`removeVolume('${esc(v.id)}')`)}</div></div><p>${esc(v.description||'尚未填寫篇章簡介')}</p><div class="ir-chapters">${v.chapters.map((c,ci)=>`<div class="ir-chapter"><span>${String(ci+1).padStart(2,'0')}</span><div><strong>${esc(c.title)}</strong><small>${c.scenes.length} 個場景${data.bookmarks[c.id]?' · 已放置書籤':''}</small></div>${button('進入 ↗',`play('${esc(v.id)}','${esc(c.id)}')`)}${data.bookmarks[c.id]?button('續讀',`play('${esc(v.id)}','${esc(c.id)}',true)`):''}${button('編輯',`editChapter('${esc(v.id)}','${esc(c.id)}')`)}${button('刪除',`removeChapter('${esc(v.id)}','${esc(c.id)}')`)}</div>`).join('')}</div>${button('＋ 新增小章',`editChapter('${esc(v.id)}')`,'ir-add')}</div></section>`).join(''):`<div class="ir-empty"><div class="ir-reticle">＋</div><small>AWAITING FIRST SESSION</small><h4>建立第一份審訊檔案</h4><p>新增篇章，再加入小章、CG 與對話。也可以先預覽範例。</p>${button('建立篇章','editVolume()')}${button('預覽互動範例','demo()')}</div>`}</div>`;scroll.scrollTop=top;}
  function editVolume(id=''){if(!canEdit())return;const data=ensureData();if(!data)return;shell();const v=data.volumes.find(v=>v.id===id),number=['一','二','三','四','五','六','七','八','九','十'][data.volumes.length]||String(data.volumes.length+1);volumeId=id;draft={kind:'volume',id:v?.id||uid(),title:v?.title||`審訊室（${number}）`,description:v?.description||''};showEditor();}

