  const freshScene=()=>({id:uid(),speaker:char()?.name||'人物',text:'',emotion:'平靜',cg:'',overlay:'',overlayY:28,overlayWidth:100,bgm:'',se:'',variants:[],choices:[]});
  function shell(){if($('irPlayer'))return;const player=document.createElement('div');player.id='irPlayer';player.className='ir-modal ir-player';player.hidden=true;player.setAttribute('role','dialog');player.setAttribute('aria-modal','true');player.setAttribute('aria-label','人物審訊室');player.innerHTML=`<div class="ir-player-shell"><header>${button('← 檔案目錄','exitPlayer()')}<span id="irPlayerTitle"></span><button type="button" id="irMenuToggle" aria-label="閱讀選單" aria-expanded="false" aria-controls="irDrawer" onclick="OCInterrogation.toggleDrawer()">☰</button></header><main class="ir-stage" id="irStage"><div class="ir-stage-grid"></div><img id="irBackground" class="ir-background" alt="背景" hidden><div class="ir-camera" id="irCamera"><img id="irCGPrevious" class="ir-cg ir-cg-previous" alt="" aria-hidden="true" hidden><img id="irCG" class="ir-cg" alt="人物主 CG" hidden></div><div id="irPlaceholder" class="ir-placeholder"><div class="ir-reticle">＋</div><small>INTERROGATION / LIVE</small><span id="irSubject"></span></div><img id="irOverlay" class="ir-overlay" alt="疊加 CG" hidden><span class="ir-stage-label">REC <b>●</b> / PRIVATE SESSION <em>VOICE RECORD</em></span><div class="ir-dialogue-zone"><div class="ir-scene-meta" id="irSceneMeta"></div><article class="ir-dialogue" id="irDialogue"><div class="ir-nameplate" id="irNameplate"><h2 id="irSpeaker"></h2><span id="irSpeakerEnglish"></span></div><p id="irText" aria-live="polite"></p><div id="irContinue"></div></article><div class="ir-choices" id="irChoices"></div></div></main><footer><small>點擊畫面繼續 · 選項需先選擇</small><button type="button" id="irSkip" class="ir-skip" aria-pressed="false" onclick="OCInterrogation.skip()" aria-label="SKIP 快進，自動選擇第一個選項" title="SKIP 快進，自動選擇第一個選項"><svg viewBox="0 0 32 24" aria-hidden="true"><path d="m3 4 11 8L3 20ZM17 4l11 8-11 8Z"/></svg><span>SKIP</span></button><span id="irAudioStatus" role="status"></span></footer><nav id="irDrawer" class="ir-drawer" aria-label="閱讀工具" hidden><small>PRIVATE SESSION / 閱讀工具</small>${button('回顧','panel("log")')}${button('書籤','bookmark()','ir-bookmark-button')}${button('即時編輯','editCurrent()')}${button('字體 / 音量','panel("settings")')}</nav><aside id="irPanel" hidden></aside><section id="irBookmarkPrompt" class="ir-bookmark-prompt" hidden><div><small>READING BOOKMARK</small><h2>找到閱讀書籤</h2><p id="irBookmarkPreview"></p><button type="button" onclick="OCInterrogation.resolveBookmark(true)">從書籤續讀</button><button type="button" onclick="OCInterrogation.resolveBookmark(false)">移除書籤，從頭開始</button><button type="button" onclick="OCInterrogation.resolveBookmark(null)">返回目錄</button></div></section><section id="irEnding" class="ir-ending" hidden aria-label="訊問結束"><div class="ir-ending-card"><small>PRIVATE DOSSIER / SESSION CLOSED</small><div class="ir-ending-seal" aria-hidden="true">◇</div><h2>訊問結束</h2><p class="ir-session-person" id="irEndingPerson"></p><p id="irEndingTitle"></p><span class="ir-ending-rule"></span><p class="ir-ending-note">燈光漸暗，未說完的故事，留待下一次相遇。</p><small id="irEndingMeta"></small><div class="ir-ending-actions"><button type="button" onclick="OCInterrogation.exitPlayer()">返回篇章目錄</button><button type="button" onclick="OCInterrogation.restart()">再次閱讀</button></div></div></section><div class="ir-entry" id="irEntry"><small>ACCESS GRANTED</small><strong>人物審訊室</strong><p class="ir-session-person" id="irEntryPerson"></p><span>建立私人連線 · 載入人物檔案</span></div></div>`;document.body.append(player);const loading=document.createElement('div');loading.id='irPreload';loading.className='ir-modal ir-preload';loading.hidden=true;loading.setAttribute('role','dialog');loading.setAttribute('aria-label','準備審訊素材');loading.innerHTML='<div class="ir-preload-card"><small>PRIVATE DOSSIER / PREPARING</small><div class="ir-preload-orbit" aria-hidden="true">◇</div><h2 id="irPreloadPerson"></h2><p>正在準備本章畫面</p><progress id="irPreloadProgress" max="1" value="0"></progress><span id="irPreloadStatus" role="status"></span><button type="button" onclick="OCInterrogation.cancelPreload()">返回目錄</button></div>';document.body.append(loading);player.addEventListener('selectstart',event=>event.preventDefault());player.querySelectorAll('img').forEach(img=>img.draggable=false);player.querySelector('.ir-stage').addEventListener('click',event=>{if(performance.now()<suppressTapUntil)return;if(skipTimer){stopSkip();return;}if(event.target.closest('button,a,input,select,textarea')||!$('irPanel').hidden||!$('irEditor').hidden)return;if(!$('irDrawer').hidden){toggleDrawer(false);return;}next();});mountHold(player.querySelector('.ir-stage'));
    const editor=document.createElement('div');editor.id='irEditor';editor.className='ir-modal ir-editor';editor.hidden=true;editor.setAttribute('role','dialog');editor.setAttribute('aria-modal','true');editor.setAttribute('aria-label','審訊室編輯器');editor.innerHTML=`<form class="ir-editor-shell" onsubmit="OCInterrogation.saveEditor(event)"><header><div><small>DOSSIER / LIVE EDITOR</small><h3>審訊劇本工作台</h3></div>${button('關閉','closeEditor()')}</header><div class="ir-editor-meta" id="irEditorMeta"></div><div class="ir-editor-workspace"><nav id="irSceneList"></nav><section id="irSceneFields"></section></div><p id="irEditorStatus" role="status"></p><footer><span>選項差分 → 回應 → 自動接回下一個場景</span>${button('取消','closeEditor()')}<button type="submit" class="ir-primary">儲存並套用</button></footer></form>`;document.body.append(editor);
    document.addEventListener('keydown',e=>{if($('irPreload')&&!$('irPreload').hidden){if(e.key==='Escape'){e.preventDefault();cancelPreload();}trap(e,$('irPreload'));return;}if($('apiKeyModal')?.classList.contains('active'))return;if(!$('irEditor').hidden){if(e.key==='Escape'){e.preventDefault();closeEditor();}trap(e,editor);return;}if(!player.hidden){if(e.key==='Escape'){e.preventDefault();if(!$('irPanel').hidden)$('irPanel').hidden=true;else if(!$('irDrawer').hidden)toggleDrawer(false);else exitPlayer();}else if((e.key===' '||e.key==='ArrowRight')&&!/INPUT|TEXTAREA|SELECT|BUTTON/.test(e.target.tagName)){e.preventDefault();next();}trap(e,player);}});
  }
  function trap(e,el){if(e.key!=='Tab')return;const list=[...el.querySelectorAll('button,input,textarea,select,[tabindex="0"]')].filter(n=>!n.disabled&&n.getClientRects().length);const first=list[0],last=list.at(-1);if(!first)return;if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
  function editChapter(vid,cid=''){if(!canEdit())return;volumeId=vid;chapterId=cid;const v=volume();if(!v)return;shell();draft=JSON.parse(JSON.stringify(chapter()||{id:uid(),title:`${v.title}:${String(v.chapters.length+1).padStart(2,'0')}`,cg:'',bgm:'',emotions:{},scriptText:(char()?.name||'人物')+'｜從這裡開始寫下對話。',scenes:[freshScene()]}));sceneIndex=0;showEditor();}
  function editCurrent(){if(!canEdit())return;toggleDrawer(false);if(session?.demo)return;draft=JSON.parse(JSON.stringify(chapter()));sceneIndex=Math.min(session?.index||0,draft.scenes.length-1);showEditor();}
  function showEditor(){window.OCVnPolish?.close();theme($('irEditor'));const isVolume=draft.kind==='volume';$('irEditor').classList.toggle('ir-volume-editor',isVolume);$('irEditor').querySelector('.ir-editor-workspace').hidden=isVolume;$('irEditor').querySelector('header h3').textContent=isVolume?'篇章檔案':'直版視覺小說編輯器';$('irEditor').querySelector('footer span').textContent=isVolume?'每個篇章可加入多個獨立小章。':'@choose → @[選項] → @choose_off → 共通劇情';if(isVolume){$('irEditorMeta').innerHTML=field('title','篇章名稱',draft.title)+area('description','篇章簡介',draft.description);}else{draft.cg||='';draft.bgm||='';draft.emotions||={};draft.scriptText=OCVnScript.serialize(draft);$('irEditorMeta').innerHTML=field('title','小章標題',draft.title)+field('cg','預設主 CG 網址',draft.cg)+field('bgm','全局 BGM 網址',draft.bgm)+area('emotions','情緒 CG 對應（每行：情緒 | 網址或 asset:ID）',Object.entries(draft.emotions||{}).map(([k,v])=>k+' | '+v).join('\n'));$('irSceneList').hidden=true;$('irSceneFields').innerHTML=speakerTools()+'<div class="ir-script-tools">'+button('CG',"insertScript('cg')")+button('疊加 CG',"insertScript('overlay')")+button('BGM',"insertScript('bgm')")+button('音效',"insertScript('se')")+button('情緒',"insertScript('emotion')")+button('震動',"insertScript('shake')")+button('選項模組',"choiceBuilder()")+button('單一選項',"choiceBuilder(1)")+button('讀入文字腳本','importScript()')+button('下載文字腳本','downloadScript()')+'</div><label>可手動編輯的視覺小說腳本<textarea id="irScriptText" rows="18" spellcheck="false"></textarea></label><details class="ir-script-help"><summary>指令與選項語法</summary><p>人物（情緒）｜台詞，或 @emotion 情緒。台詞沒有說話人時視為旁白。</p><p>選項可以只有一個；玩家點選後才會繼續。可使用「單一選項」快速插入。</p><p>@cg 網址 · @bg 網址 · @overlay 網址 · @overlay_position 28 100 · @bgm 網址 · @bgm none · @se 網址 · @shake</p><p>@hide all · @closer c · @closer off · @move c 20 -10 1 · @move c default · @jump c · @flip c on · @scale c 1.2 1</p><pre>旁白｜你要選 A 還是 B？\n@choose\nA,B\n@[A]\n人物（微笑）｜A 的第一句。\n接下來也是 A 的內容。\n@[B]\n人物（警戒）｜B 的第一句。\n@choose_off\n旁白｜回到共通劇情。</pre></details><div class="ir-upload-row">'+uploadControl('cg','上傳 CG','image/*')+uploadControl('overlay','上傳疊加 CG','image/*')+uploadControl('bgm','上傳 BGM','audio/*')+uploadControl('se','上傳音效','audio/*')+'</div>';$('irScriptText').value=draft.scriptText;mountHighlight();const speakerDock=$('irSceneFields').querySelector('.ir-speaker-tools');$('irScriptText').closest('label').after(speakerDock);speakerDock.classList.add('ir-speaker-dock');speakerDock.after($('irSceneFields').querySelector('.ir-script-tools'));refreshEmotionOptions();$('irEditorMeta').querySelector('[data-field=emotions]').addEventListener('input',refreshEmotionOptions);window.OCVnPolish?.mount({owner:char(),config:draft.polish});draft.polish=window.OCVnPolish?.config()||draft.polish;}editorSnapshot=JSON.stringify(draft);$('irEditorStatus').textContent='';$('irEditor').hidden=false;$('irEditorMeta').querySelector('input').focus();}

  function collect(){if(!draft)return;const meta=Object.fromEntries([...$('irEditorMeta').querySelectorAll('[data-field]')].map(n=>[n.dataset.field,n.value]));draft.title=meta.title;if(draft.kind==='volume'){draft.description=meta.description;return;}draft.cg=meta.cg;draft.bgm=meta.bgm;draft.emotions=Object.fromEntries(meta.emotions.split('\n').map(s=>s.split('|').map(x=>x.trim())).filter(a=>a.length===2&&a[0]&&a[1]));draft.scriptText=$('irScriptText').value;draft.polish=window.OCVnPolish?.config()||draft.polish;}
  function speakerTools(){const current=char(),rows=characters.filter(c=>c.name).slice().sort((a,b)=>Number(String(b.id)===String(current?.id))-Number(String(a.id)===String(current?.id)));return '<div class="ir-speaker-tools"><div class="ir-speaker-caption"><small>說話人</small><span>在游標處插入台詞標記</span></div><div class="ir-speaker-controls">'+button('旁白｜',"insertSpeaker('narrator')",'ir-speaker-button')+button(esc((current?.name||'人物')+'｜'),"insertSpeaker('current')",'ir-speaker-button')+'<label class="ir-speaker-picker"><span class="sr-only">選擇說話角色</span><select id="irSpeakerSelect" aria-label="選擇說話角色" onchange="OCInterrogation.refreshEmotionOptions()">'+rows.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.name)+'</option>').join('')+'</select></label>'+'<label class="ir-emotion-picker"><span class="sr-only">選擇已登記情緒</span><select id="irEmotionSelect" aria-label="選擇已登記情緒"><option value="">不指定情緒</option></select></label>'+button('插入角色｜',"insertSpeaker('selected')",'ir-speaker-insert')+'</div></div>';}

  function refreshEmotionOptions(){const picker=$('irEmotionSelect');if(!picker)return;const before=picker.value,selected=characters.find(c=>String(c.id)===String($('irSpeakerSelect')?.value)),registered=$('irEditorMeta').querySelector('[data-field=emotions]')?.value||'',moods=new Set(registered.split('\n').map(line=>line.split('|')[0].trim()).filter(Boolean));picker.innerHTML='<option value="">不指定情緒</option>'+[...moods].map(mood=>'<option value="'+esc(mood)+'">'+esc(mood)+'</option>').join('');if(moods.has(before))picker.value=before;}

  function insertSpeaker(kind='selected'){const editor=$('irScriptText');if(!editor)return;const selected=characters.find(c=>String(c.id)===String($('irSpeakerSelect')?.value)),name=kind==='narrator'?'旁白':kind==='current'?char()?.name:selected?.name;if(!name)return;const start=editor.selectionStart??editor.value.length,scroll=editor.scrollTop,container=$('irSceneFields'),containerScroll=container.scrollTop;const mood=kind==='narrator'?'':$('irEmotionSelect')?.value||'';const prefix=(start&&!editor.value.slice(0,start).endsWith('\n')?'\n\n':'')+String(name).replace(/[\r\n｜|]/g,' ')+(mood?'（'+mood.replace(/[\r\n（）()]/g,' ')+'）':'')+'｜';editor.setRangeText(prefix,start,start,'end');editor.dispatchEvent(new Event('input',{bubbles:true}));editor.focus({preventScroll:true});editor.scrollTop=scroll;container.scrollTop=containerScroll;}
  function insertScript(type,value){if(type==='choose'||type==='choose_single'){choiceBuilder(type==='choose_single'?1:2);return;}const editor=$('irScriptText');if(!editor)return;let command;if(type==='choose')command='@choose\nA,B\n@[A]\n旁白｜A 的劇情。\n@[B]\n旁白｜B 的劇情。\n@choose_off';else if(type==='choose_single')command='@choose\n我準備好了。\n@[我準備好了。]\n@choose_off';else if(type==='shake')command='@shake';else{if(value===undefined){value=prompt(type==='emotion'?'輸入情緒名稱':'輸入素材網址或 asset:ID');if(!value)return;}command='@'+type+' '+value;}const start=editor.selectionStart,end=editor.selectionEnd;editor.setRangeText((start&&!editor.value.slice(0,start).endsWith('\n')?'\n\n':'')+command+'\n\n',start,end,'end');editor.dispatchEvent(new Event('input',{bubbles:true}));editor.focus();}
  function importScript(){const input=document.createElement('input');input.type='file';input.accept='.txt,text/plain';input.onchange=async()=>{try{$('irScriptText').value=OCVnScript.normalize(await input.files[0].text());$('irScriptText').dispatchEvent(new Event('input',{bubbles:true}));}catch(e){$('irEditorStatus').textContent=e.message;}};input.click();}

  let choiceRange=null,highlightObserver=null;
  function mountHighlight(){highlightObserver?.disconnect();const editor=$('irScriptText'),wrap=document.createElement('div');wrap.className='ir-script-code';editor.before(wrap);const pre=document.createElement('pre');pre.id='irScriptHighlight';pre.setAttribute('aria-hidden','true');wrap.append(pre,editor);const sync=()=>{pre.scrollTop=editor.scrollTop;pre.scrollLeft=editor.scrollLeft;};const paint=()=>{pre.innerHTML=editor.value.split('\n').map((line,index)=>{const bad=Number(editor.dataset.errorLine)===index+1,command=/^\s*@/.test(line);return '<span'+(bad?' data-error-line="'+(index+1)+'"':'')+' class="'+(command?'ir-command ':'')+(bad?'ir-script-error':'')+'">'+esc(line||' ')+'</span>';}).join('\n')+'\n '; sync();};editor.addEventListener('input',()=>{if(editor.dataset.errorLine){delete editor.dataset.errorLine;editor.removeAttribute('aria-invalid');editor.removeAttribute('aria-describedby');$('irEditorStatus').textContent='';}paint();});editor.addEventListener('ir-highlight',paint);editor.addEventListener('scroll',sync);highlightObserver=new ResizeObserver(()=>{pre.style.width=editor.clientWidth+'px';const style=getComputedStyle(editor);for(const key of ['fontSize','lineHeight','padding','letterSpacing','tabSize'])pre.style[key]=style[key];sync();});highlightObserver.observe(editor);paint();}
  function choiceBuilder(count=2){const editor=$('irScriptText');if(!editor||!canEdit())return;$('irChoiceBuilder')?.remove();const start=editor.selectionStart,end=editor.selectionEnd,lines=editor.value.split('\n');let pos=0,stack=[],found=null;for(let i=0;i<lines.length;i++){const line=lines[i].trim();if(/^@choose$/i.test(line))stack.push({line:i,start:pos});if(/^@choose_off$/i.test(line)&&stack.length){const block=stack.pop();block.end=pos+lines[i].length;block.endLine=i;if(start>=block.start&&end<=block.end&&(!found||block.start>found.start))found=block;}pos+=lines[i].length+1;}choiceRange=found?{start:found.start,end:found.end,source:editor.value}:{start,end,source:editor.value};const panel=document.createElement('section');panel.id='irChoiceBuilder';panel.className='ir-choice-builder';panel.innerHTML='<div class="ir-heading"><h4>選項模組</h4>'+button('收起',"closeChoiceBuilder()")+'</div><p>每個分支可展開／收合，也能加入下一層選項。子選項結束後接回本分支，整層結束後回到外層。劇情可留空。</p><div id="irChoiceRows"></div><div class="ir-choice-builder-actions">'+button('＋ 增加選項',"addChoiceRow()")+button(found?'更新此選項模組':'插入到游標位置',"applyChoiceBuilder()",'ir-primary')+'</div><p id="irChoiceStatus" role="status"></p>';$('irScriptText').closest('label').before(panel);if(found){for(const row of groupRows(lines.slice(found.line,found.endLine+1).join('\n')))addChoiceRow(row.label,row.body);if(!$('irChoiceRows').children.length)addChoiceRow();}else for(let i=0;i<count;i++)addChoiceRow(count===1?'我準備好了。':i===0?'先說說那一天。':'我想再了解你。','');panel.scrollIntoView({block:'nearest',behavior:'smooth'});panel.querySelector('input').focus({preventScroll:true});}

  function storyText(text=''){const field=document.createElement('label');field.className='ir-story-text';field.innerHTML='劇情文字<textarea rows="3" placeholder="人物｜台詞，或直接寫旁白。"></textarea>';field.querySelector('textarea').value=text;field.querySelector('textarea').addEventListener('focus',event=>event.target.dataset.cursorUsed='true');return field;}
  function groupRows(script){const lines=script.split('\n');let depth=0,current=null,rows=[];for(let i=2;i<lines.length-1;i++){const line=lines[i].trim();if(/^@choose$/i.test(line))depth++;if(/^@choose_off$/i.test(line))depth--;const marker=depth===0?line.match(/^@\[(.+)\]$/):null;if(marker){current={label:marker[1],lines:[]};rows.push(current);}else if(current)current.lines.push(lines[i]);}return rows.map(row=>({label:row.label,body:row.lines.join('\n')}));}
  function renderStory(host,body){const lines=body.split('\n');let textStart=0;for(let i=0;i<lines.length;i++){if(!/^\s*@choose\s*$/i.test(lines[i]))continue;let depth=1,end=i+1;for(;end<lines.length;end++){if(/^\s*@choose\s*$/i.test(lines[end]))depth++;if(/^\s*@choose_off\s*$/i.test(lines[end])&&--depth===0)break;}if(depth!==0)continue;host.append(storyText(lines.slice(textStart,i).join('\n')));const group=makeNestedGroup();host.append(group);const rows=groupRows(lines.slice(i,end+1).join('\n'));for(const row of rows)addChoiceRow(row.label,row.body,group.querySelector('.ir-choice-rows'));i=end;textStart=end+1;}host.append(storyText(lines.slice(textStart).join('\n')));}
  function addChoiceRow(label='',body='',target){const host=target||$('irChoiceRows');if(!host)return;const row=document.createElement('details');row.className='ir-choice-module';row.open=true;row.innerHTML='<summary><span class="ir-choice-level"></span><strong class="ir-choice-summary">新選項</strong><span class="ir-fold-hint">展開／收合</span></summary><div class="ir-choice-content"><div class="ir-heading"><label>玩家看到的按鈕文字<input class="ir-choice-label" placeholder="例如：我準備好了。"></label><button type="button" onclick="this.closest(\'.ir-choice-module\').remove();OCInterrogation.refreshChoiceLevels()">移除</button></div><div class="ir-story-parts"></div><button class="ir-nested-add" type="button" onclick="OCInterrogation.addNestedChoice(this.closest(\'.ir-choice-module\'))">＋ 在此分支加入下一層選項</button></div>';row.querySelector('input').value=label;row.querySelector('input').addEventListener('input',refreshChoiceLevels);host.append(row);renderStory(row.querySelector('.ir-story-parts'),body);refreshChoiceLevels();return row;}
  function makeNestedGroup(){const group=document.createElement('details');group.className='ir-nested-group';group.open=true;group.innerHTML='<summary><strong class="ir-group-level">下一層選項</strong><span class="ir-fold-hint">展開／收合</span></summary><p>這裡的選項結束後，接回本分支下面的劇情。</p><div class="ir-choice-rows"></div><div class="ir-nested-actions"><button type="button" onclick="OCInterrogation.addChoiceRow(\'\',\'\',this.closest(\'.ir-nested-group\').querySelector(\'.ir-choice-rows\'))">＋ 增加此層選項</button><button type="button" onclick="this.closest(\'.ir-nested-group\').remove();OCInterrogation.refreshChoiceLevels()">移除此層選項</button></div>';return group;}
  function addNestedChoice(row){if(!row)return;const host=row.querySelector('.ir-story-parts'),last=host.lastElementChild,editor=last?.matches('.ir-story-text')?last.querySelector('textarea'):null;let after='';if(editor){const cursor=editor.dataset.cursorUsed==='true'?editor.selectionStart:editor.value.length;after=editor.value.slice(cursor);editor.value=editor.value.slice(0,cursor);if(!editor.value.trim())editor.value=(char()?.name||'人物')+'｜你想繼續問哪一件事？';}const group=makeNestedGroup();host.append(group);addChoiceRow('繼續追問。','',group.querySelector('.ir-choice-rows'));addChoiceRow('換個問題。','',group.querySelector('.ir-choice-rows'));host.append(storyText(after));refreshChoiceLevels();group.scrollIntoView({block:'nearest',behavior:'smooth'});}
  function refreshChoiceLevels(){const root=$('irChoiceRows');if(!root)return;const visit=(host,depth,prefix)=>{[...host.children].forEach((row,index)=>{const path=prefix+(index+1);row.querySelector('.ir-choice-level').textContent='第 '+depth+' 層 · '+path;row.querySelector('.ir-choice-summary').textContent=row.querySelector('.ir-choice-label').value.trim()||'未命名選項';row.style.setProperty('--ir-choice-depth',depth);const groups=[...row.querySelector('.ir-story-parts').children].filter(el=>el.matches('.ir-nested-group'));groups.forEach((group,i)=>{group.querySelector('.ir-group-level').textContent='第 '+(depth+1)+' 層選項'+(groups.length>1?' · 區塊 '+(i+1):'');visit(group.querySelector('.ir-choice-rows'),depth+1,path+'.');});});};visit(root,1,'');}
  function serializeChoiceGroup(host){const rows=[...host.children].map(row=>({label:row.querySelector('.ir-choice-label').value.trim(),body:[...row.querySelector('.ir-story-parts').children].map(part=>part.matches('.ir-nested-group')?serializeChoiceGroup(part.querySelector('.ir-choice-rows')):part.querySelector('textarea').value.trim()).filter(Boolean).join('\n')}));if(!rows.length)throw Error('每一層請保留至少一個選項。');if(rows.some(row=>!row.label||/[\r\n]/.test(row.label)))throw Error('請填寫每個選項的按鈕文字。');if(new Set(rows.map(row=>row.label)).size!==rows.length)throw Error('同一層每個選項的按鈕文字需要不同。');return ['@choose',JSON.stringify(rows.map(row=>row.label)),...rows.flatMap(row=>['@['+row.label+']',row.body]),'@choose_off'].filter(Boolean).join('\n');}

  function closeChoiceBuilder(){$('irChoiceBuilder')?.remove();choiceRange=null;}
  function showScriptError(error){const editor=$('irScriptText'),line=Number(error.line)||Number(String(error.message).match(/第\s*(\d+)\s*行/)?.[1]);if(editor&&line>0){editor.dataset.errorLine=line;editor.setAttribute('aria-invalid','true');editor.setAttribute('aria-describedby','irEditorStatus');editor.dispatchEvent(new Event('ir-highlight'));const lines=editor.value.split('\n'),start=lines.slice(0,line-1).reduce((n,v)=>n+v.length+1,0);editor.focus({preventScroll:true});editor.setSelectionRange(start,start);editor.scrollTop=Math.max(0,($('irScriptHighlight').querySelector('[data-error-line]')?.offsetTop||0)-editor.clientHeight*.35);editor.dispatchEvent(new Event('scroll'));editor.closest('.ir-script-code').scrollIntoView({block:'nearest'});}$('irEditorStatus').textContent=error.message;}
  function applyChoiceBuilder(){const status=$('irChoiceStatus');let script;try{script=serializeChoiceGroup($('irChoiceRows'));OCVnScript.compile(script);}catch(error){status.textContent=error.message;return;}const editor=$('irScriptText'),range=choiceRange;if(!range)return;if(editor.value!==range.source){status.textContent='劇本文字已改動，請收起後重新開啟選項模組，避免覆蓋其他內容。';return;}const prefix=range.start&&!editor.value.slice(0,range.start).endsWith('\n')?'\n\n':'',suffix=editor.value.slice(range.end).startsWith('\n')?'':'\n\n';editor.setRangeText(prefix+script+suffix,range.start,range.end,'end');editor.dispatchEvent(new Event('input',{bubbles:true}));closeChoiceBuilder();editor.focus();$('irEditorStatus').textContent='多層選項已加入；各層標記與共通劇情銜接已自動配對。';}
  function downloadScript(){const url=URL.createObjectURL(new Blob([$('irScriptText').value],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=(draft.title||'審訊劇本')+'.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

  function uploadControl(key,label,accept){return `<label class="ir-upload">${label}<input type="file" accept="${accept}" onchange="OCInterrogation.upload('${key}',this)"></label>`;}
  async function upload(key,input){const file=input.files?.[0];if(!file)return;const expected=key==='cg'||key==='overlay'?'image/':'audio/';if(!file.type.startsWith(expected)){$('irEditorStatus').textContent='檔案類型不符。';return;}if(file.size>50*1024*1024){$('irEditorStatus').textContent='請使用 50 MB 以下檔案。';return;}const target=draft;try{if(!window.OCFeatures?.storeFile)throw Error('本地素材儲存不可用');$('irEditorStatus').textContent='儲存素材中…';const id=uid(),assetType=key==='overlay'?'cg':key;await OCFeatures.storeFile(id,file);mediaLibrary.push({id,kind:'vn-asset',assetType,title:file.name,type:file.type,size:file.size,createdAt:Date.now(),localOnly:true});persist();const url=`asset:${id}`;if(draft!==target)return;insertScript(key,url);$('irEditorStatus').textContent='素材已加入共用素材庫；請儲存劇本以套用。';}catch(e){$('irEditorStatus').textContent=`上傳失敗：${e.message}`;}}
  function closeEditor(force=false){if(!$('irEditor')||$('irEditor').hidden)return true;collect();if(!force&&JSON.stringify(draft)!==editorSnapshot&&!confirm('劇本尚未儲存，放棄修改？'))return false;window.OCVnPolish?.close();$('irEditor').hidden=true;draft=null;if(session&&!$('irPlayer').hidden)$('irPlayer').querySelector('header button').focus();else $('irTabs')?.children[1].focus();return true;}
  function saveEditor(event){event.preventDefault();if(!canEdit())return;collect();if(!draft.title.trim()){$('irEditorStatus').textContent='請填寫小章標題。';return;}if(draft.kind==='volume'){const data=ensureData(),v=data.volumes.find(v=>v.id===draft.id);if(v){v.title=draft.title.trim();v.description=draft.description;}else data.volumes.push({id:draft.id,title:draft.title.trim(),description:draft.description,chapters:[]});persist();closeEditor(true);directory();return;}const v=volume();if(!v)return;let compiled;try{compiled=OCVnScript.compile(draft.scriptText,draft,line=>parseVisualNovelScript(line)[0]);}catch(error){showScriptError(error);return;}draft.scenes=compiled.scenes;draft.entry=compiled.entry;draft.scriptVersion=2;const currentSceneId=session?.chapter.scenes[session.index]?.id;const id=draft.id,index=v.chapters.findIndex(c=>c.id===id);if(index<0)v.chapters.push(draft);else v.chapters[index]=draft;chapterId=id;persist();closeEditor(true);directory();if(session&&!$('irPlayer').hidden){session.chapter=chapter();const sameIndex=session.chapter.scenes.findIndex(s=>s.id===currentSceneId);session.index=sameIndex>=0?sameIndex:Math.min(session.index,session.chapter.scenes.length-1);if(sameIndex<0){session.reply=null;session.choiceIndex=null;}else if(session.reply&&Number.isInteger(session.choiceIndex)){const updated=session.chapter.scenes[session.index].choices[session.choiceIndex];if(updated)session.reply={...updated,response:updated.response||'（沉默）'};}draw(true);}}
  function start(c,bookmark,demo=false){shell();stopSkip();$('irBookmarkPrompt').hidden=true;refreshEditing();const prefs=ensureData().settings;if(prefs.readerUiVersion!==5){if(!prefs.font||prefs.font===20)prefs.font=18;else prefs.font=Math.max(16,prefs.font);prefs.readerUiVersion=5;persist();}returnFocus=document.activeElement;session={openingUntil:performance.now()+1500,chapter:c,index:c.entry||0,trust:0,reply:null,log:[],visited:{},demo,...JSON.parse(JSON.stringify(bookmark||{}))};session.chapter=c;session.demo=demo;if(bookmark?.bookmarkText&&!bookmark.reply){const matches=c.scenes.map((row,index)=>({row,index})).filter(x=>x.row.text===bookmark.bookmarkText);if(matches.length)session.index=matches.reduce((best,x)=>Math.abs(x.index-(bookmark.index||0))<Math.abs(best.index-(bookmark.index||0))?x:best,matches[0]).index;else if(bookmark.sceneId){const index=c.scenes.findIndex(row=>row.id===bookmark.sceneId);if(index>=0)session.index=index;}}else if(bookmark?.sceneId){const savedIndex=c.scenes.findIndex(s=>s.id===bookmark.sceneId);if(savedIndex>=0)session.index=savedIndex;}session.index=Math.max(0,Math.min(session.index,c.scenes.length-1));theme($('irPlayer'));$('irPlayer').hidden=false;$('irEnding').hidden=true;$('irPanel').hidden=true;toggleDrawer(false);$('irEntry').classList.remove('run');void $('irEntry').offsetWidth;$('irEntry').classList.add('run');$('irPlayerTitle').textContent=c.title;$('irSubject').textContent=char()?.name||'';$('irEntryPerson').textContent=char()?.name||'';$('irPlayer').querySelector('header button').focus();draw(!bookmark);}
  function cancelPreload(){preloadRun++;if($('irPreload'))$('irPreload').hidden=true;}
  function chapterImages(c){const first=c.scenes[c.entry||0],sources=[first?.cg==='none'?'':c.emotions?.[first?.emotion]||first?.cg||c.cg,c.cg,...Object.values(c.emotions||{})];for(const scene of c.scenes||[])sources.push(scene.cg,scene.bg,scene.overlay);return [...new Set(sources.filter(src=>src&&src!=='none'&&safeURL(src)))];}
  async function play(vid,cid,resume=false){cancelPreload();stopSkip();volumeId=vid;chapterId=cid;const c=chapter();if(!c)return;if(resume===false&&room().bookmarks[cid]){shell();theme($('irPlayer'));$('irPlayer').hidden=false;$('irBookmarkPrompt').hidden=false;const saved=room().bookmarks[cid];$('irBookmarkPreview').textContent=c.title+' · 第 '+((saved.index||0)+1)+' 句 · '+(saved.bookmarkText||c.scenes?.[saved.index]?.text||'');$('irBookmarkPrompt').querySelector('button').focus();return;}$('irBookmarkPrompt')&&($('irBookmarkPrompt').hidden=true);if(c.scriptText!==undefined){try{Object.assign(c,OCVnScript.compile(c.scriptText,c,line=>parseVisualNovelScript(line)[0]));}catch(e){alert(e.message);return;}}if(!c.scenes?.length)return;const sources=chapterImages(c);if(!sources.length){start(c,resume===true?room().bookmarks[cid]:null);return;}shell();const run=++preloadRun,owner=OCCharacterArchive.activeCharacter();theme($('irPreload'));$('irPreloadPerson').textContent=char()?.name||'';$('irPreload').hidden=false;$('irPreloadProgress').max=sources.length;$('irPreloadProgress').value=0;$('irPreloadStatus').textContent='0 / '+sources.length;let cursor=0,done=0;const worker=async()=>{while(cursor<sources.length&&run===preloadRun){const source=sources[cursor++];try{await prepareImage(source);}catch{}done++;if(run===preloadRun){$('irPreloadProgress').value=done;$('irPreloadStatus').textContent=done+' / '+sources.length;}}};let deadline;await Promise.race([Promise.all(Array.from({length:Math.min(4,sources.length)},worker)),new Promise(resolve=>deadline=setTimeout(resolve,12000))]);clearTimeout(deadline);if(run!==preloadRun||owner!==OCCharacterArchive.activeCharacter())return;$('irPreload').hidden=true;start(c,resume?room().bookmarks[cid]:null);}
  function demo(){volumeId='';chapterId='';start({title:'審訊室（一）:01 · 未說出口的事',cg:'',bgm:'',emotions:{},scenes:[{...freshScene(),text:'你終於來了。這次，你想從哪個問題開始？',choices:[{text:'從你一直避開的那件事開始。',response:'……你的直覺，還是一如既往地敏銳。',emotion:'警戒',delta:-1},{text:'先告訴我，你今天過得好嗎？',response:'我以為你會先問案情。謝謝，我好多了。',emotion:'放鬆',delta:1}]},{...freshScene(),text:'不論你怎麼問，我都會把那天發生的事告訴你。',variants:[{minTrust:1,text:'因為是你，我願意把那天的一切都說出來。'}]}]},null,true);}
  function sceneText(s,trust){return [...(s.variants||[])].filter(v=>trust>=Number(v.minTrust)).sort((a,b)=>b.minTrust-a.minTrust)[0]?.text||s.text;}
  async function resolve(src){if(!safeURL(src))return '';const result=window.OCVnAssets?.resolve?await OCVnAssets.resolve(src):src;return safeURL(result);}
  function prepareImage(src){if(!safeURL(src))return Promise.reject(Error('不支援的圖片網址'));if(imageCache.has(src))return imageCache.get(src);const pending=(async()=>{const url=await resolve(src);if(!url)throw Error('素材不存在');const probe=new Image();await new Promise((ok,fail)=>{const timer=setTimeout(()=>{probe.onload=probe.onerror=null;probe.removeAttribute('src');fail(Error('圖片載入逾時'));},8000);probe.onload=()=>{clearTimeout(timer);ok();};probe.onerror=()=>{clearTimeout(timer);fail(Error('圖片載入失敗'));};probe.src=url;});if(probe.decode)await probe.decode();return {url,probe};})();imageCache.set(src,pending);pending.catch(()=>{if(imageCache.get(src)===pending)imageCache.delete(src);});while(imageCache.size>48)imageCache.delete(imageCache.keys().next().value);return pending;}
  function hasCG(){return (!$('irCG').hidden&&$('irCG').naturalWidth>0)||(!$('irCGPrevious').hidden&&$('irCGPrevious').naturalWidth>0);}
  async function imageAt(id,src,token){const img=$(id);if(!src){img.hidden=true;img.removeAttribute('src');delete img.dataset.source;if(id==='irCG'){cgRevision++;cgFade?.cancel();cgFade=null;$('irCGPrevious').hidden=true;$('irCGPrevious').style.opacity='0';$('irPlaceholder').hidden=false;}return;}if(img.dataset.source===src){if(id==='irCG')$('irPlaceholder').hidden=hasCG();return;}try{const {url}=await prepareImage(src);if(token!==renderToken)return;if(id==='irCG'){cgRevision++;cgFade?.cancel();cgFade=null;img.style.transition='none';const previous=$('irCGPrevious');if(!img.hidden&&img.complete&&img.naturalWidth){previous.src=img.src;previous.style.transform=img.style.transform;previous.hidden=false;previous.style.transition='none';previous.style.opacity='1';void previous.offsetWidth;}img.style.opacity='0';}img.hidden=true;img.dataset.source=src;img.onload=()=>{if(img.dataset.source!==src)return;img.hidden=false;if(id==='irCG'){$('irPlaceholder').hidden=true;const revision=cgRevision,duration=window.matchMedia('(prefers-reduced-motion: reduce)').matches?0:800;cgFade=img.animate([{opacity:0},{opacity:1}],{duration,easing:'ease-in-out',fill:'forwards'});cgFade.finished.then(()=>{if(revision!==cgRevision||img.dataset.source!==src)return;img.style.opacity='1';cgFade?.cancel();cgFade=null;const previous=$('irCGPrevious');previous.hidden=true;previous.removeAttribute('src');previous.style.opacity='0';}).catch(()=>{});}};img.onerror=()=>{if(img.dataset.source!==src)return;delete img.dataset.source;imageCache.delete(src);img.hidden=true;if(id==='irCG')$('irPlaceholder').hidden=hasCG();$('irAudioStatus').textContent='圖片暫時無法載入，保留目前畫面。';};img.src=url;}catch(e){if(token===renderToken){if(id==='irCG')$('irPlaceholder').hidden=hasCG();$('irAudioStatus').textContent='圖片暫時無法載入，保留目前畫面。';}}}
  async function audioAt(src,kind,token){if(kind==='bgm'&&bgm&&src===bgmSource)return;const current=kind==='bgm'?bgm:se;current?.pause();if(kind==='bgm'){bgm=null;bgmSource=src;}else se=null;if(!src||src==='-')return;try{const url=await resolve(src);if(token!==renderToken||!url)return;const a=new Audio(url);a.loop=kind==='bgm';a.volume=Number(room().settings[kind]??.5);if(kind==='bgm')bgm=a;else se=a;a.onerror=()=>{if(token===renderToken)$('irAudioStatus').textContent='音訊載入失敗，請檢查素材。';};await a.play();}catch(e){if(token===renderToken)$('irAudioStatus').innerHTML=button('點此啟用音訊','retryAudio()');}}
  function finish(){if(!session||session.ended)return;session.ended=true;stopAudio();toggleDrawer(false);$('irEndingTitle').textContent=session.chapter.title;$('irEndingPerson').textContent=char()?.name||'';$('irEndingMeta').textContent=(char()?.name||'')+' · '+session.log.length+' 則對話紀錄';$('irEnding').hidden=false;$('irEnding').querySelector('button').focus();}
  function restart(){if(!session)return;const c=session.chapter,demo=session.demo;stopAudio();start(c,null,demo);}
